import re

SPEC = [("NUMBER", r"\d+(?:\.\d*)?"), ("NAME", r"[A-Za-z_]\w*"),
        ("OP", r">=|<=|==|[-+*/=<>()]"), ("SKIP", r"\s+"), ("MISMATCH", r".")]
MASTER = re.compile("|".join(f"(?P<{n}>{p})" for n, p in SPEC))
KEYWORDS = {"if", "then"}

def tokens(text):
    for m in MASTER.finditer(text):
        kind, value = m.lastgroup, m.group()
        if kind == "SKIP":
            continue
        if kind == "MISMATCH":
            raise SyntaxError(f"unexpected {value!r} at {m.start()}")
        if kind == "NAME" and value in KEYWORDS:
            kind = value.upper()
        yield kind, value

print(list(tokens("if x >= 2.5 then y")))
# [('IF', 'if'), ('NAME', 'x'), ('OP', '>='), ('NUMBER', '2.5'), ('THEN', 'then'), ('NAME', 'y')]
try:
    list(tokens("a = 3 $ 4"))
except SyntaxError as e:
    print(e)                     # unexpected '$' at 6
